# =============================================================================
# Auto-generated by VAE Studio — structural decoder for the VAE-NLME
# engine. Per individual: analytic PK concentrations + (optionally) an ODE for
# further dynamics (e.g. an augmented Neural-ODE), mapped to observations via
# `observe`. ζ = individual parameters (theta), z_lat = latent conditioning.
#
# Speed is the goal: predefined PK models are solved in CLOSED FORM (no ODE);
# remaining ODEs use in-place f! + StaticArrays and are meant to be driven by an
# EnsembleProblem (threaded) across patients. Encoder/ELBO/training are M2.
# =============================================================================
module StructuralDecoder

using OrdinaryDiffEq
const ODE_SILENT = try; DEVerbosity(SciMLLogging.None()); catch; false; end
using DiffEqCallbacks
using ComponentArrays
using ChainRulesCore
using StaticArrays

const PARAM_NAMES = (:ke_C, :V_C, :lambda0, :lambda1, :k1, :k2, :w0)
const LATENT_NAMES = ()
const STATE_NAMES = (:x1, :x2, :x3, :x4)
const N_STATES = 4
const HAS_RATE_DOSE = false
const OBS_NAMES = ("Tumor",)
const AI_STATES = ()

# C(t): 1-cmt · IV bolus · (V, ke) — closed-form (superposition over doses).
function pkconc_C(t, theta, dose)
    @inbounds begin
        ke = theta[1]
        V = theta[2]
        acc = 0.0
        for r in axes(dose, 1)
            td = dose[r, 1]; amt = dose[r, 2]
            if amt != 0.0 && t >= td
                dt = t - td
                acc += amt / V * exp(-ke * dt)
            end
        end
        return acc
    end
end

# ODE right-hand side. p is a ComponentArray of the differentiable params
# (theta[, latent][, nn]); doses enter via the callback (bolus) — not via p.
# tstops at each infusion start/stop so the adaptive solver resolves the box
# edges (short infusions are otherwise stepped over). dur = scalar (per subject).
function rate_tstops(dose, durs::Tuple)
    ts = eltype(dose)[]
    @inbounds for r in axes(dose, 1)
        all(==(0.0), @view dose[r, 2:end]) && continue
        push!(ts, dose[r, 1])
        for dur in durs; push!(ts, dose[r, 1] + dur); end
    end
    return unique(ts)
end

# Same, but with the durations evaluated from theta — for the ENGINE's own solves
# (`_ens_ode_one` & Co.), which bypass `solve_one`. Without these stops the adaptive
# solver, coasting along a flat stretch (e.g. from t=0 to a first dose at 72 h),
# steps clean over a 1-h infusion box and the dose never enters the system.
function rate_tstops_theta(theta, dose)
    ke_C = theta[1]
    V_C = theta[2]
    lambda0 = theta[3]
    lambda1 = theta[4]
    k1 = theta[5]
    k2 = theta[6]
    w0 = theta[7]
    return rate_tstops(dose, ())
end

# Batched tstops: dose (N,nd,1+k), durs a tuple of length-N vectors.
function rate_tstops_batch(dose, durs::Tuple)
    ts = Float64[]
    @inbounds for i in axes(dose, 1), r in axes(dose, 2)
        all(==(0.0), @view dose[i, r, 2:end]) && continue
        push!(ts, dose[i, r, 1])
        for dur in durs; push!(ts, dose[i, r, 1] + dur[i]); end
    end
    return unique(ts)
end

function f!(du, u, p, t, dose)
    theta = view(p, 1:7)
    @inbounds begin
        ke_C = theta[1]
        V_C = theta[2]
        lambda0 = theta[3]
        lambda1 = theta[4]
        k1 = theta[5]
        k2 = theta[6]
        w0 = theta[7]
        x1 = u[1]
        x2 = u[2]
        x3 = u[3]
        x4 = u[4]
        C = pkconc_C(t, theta, dose)
        w = x1 + x2 + x3 + x4
        du[1] = lambda0*x1/(1 + (lambda0/lambda1*w)^20)^(1/20) - k2*C*x1
        du[2] = k2*C*x1 - k1*x2
        du[3] = k1*(x2 - x3)
        du[4] = k1*(x3 - x4)
    end
    return nothing
end

function y0(theta)
    ke_C = theta[1]
    V_C = theta[2]
    lambda0 = theta[3]
    lambda1 = theta[4]
    k1 = theta[5]
    k2 = theta[6]
    w0 = theta[7]
    return vcat(float(w0), float(0), float(0), float(0))
end

function solve_one(theta, latent, nn, dose, tspan, saveat;
                   solver = Tsit5(), abstol = 1e-4, reltol = 1e-4,
                   sensealg = nothing)
    p = vcat(theta)
    _rts = @ignore_derivatives rate_tstops(dose, ())
    u0 = y0(theta)
    prob = ODEProblem((du, u, pp, tt) -> f!(du, u, pp, tt, dose), u0, tspan, p)
    ss = tspan[1] == first(saveat)
    return solve(prob, solver; verbose = ODE_SILENT, saveat = saveat, save_start = ss,
                 abstol = abstol, reltol = reltol, tstops = _rts,
                 save_everystep = false, sensealg = sensealg)
end

function pkconc_bat_C(theta, dose, t)
    N = size(theta, 2); nd = size(dose, 2)
    ke = reshape(view(theta, 1, :), N, 1)
    V = reshape(view(theta, 2, :), N, 1)
    td  = reshape(view(dose, :, :, 1), N, nd)
    amt = reshape(view(dose, :, :, 2), N, nd)
    rawdt = t .- td
    active = @. (amt != 0.0) & (rawdt >= 0.0)
    dt = @. max(rawdt, zero(eltype(rawdt)))
    contrib = @. (amt / V * exp(-ke * dt)) * active
    return dropdims(sum(contrib, dims = 2), dims = 2)
end

function f_batch!(du, u, p, t, dose)
    theta = p.theta
    @inbounds begin
        ke_C = @view theta[1, :]
        V_C = @view theta[2, :]
        lambda0 = @view theta[3, :]
        lambda1 = @view theta[4, :]
        k1 = @view theta[5, :]
        k2 = @view theta[6, :]
        w0 = @view theta[7, :]
        x1 = @view u[1, :]
        x2 = @view u[2, :]
        x3 = @view u[3, :]
        x4 = @view u[4, :]
        C = pkconc_bat_C(theta, dose, t)
        w = @. (x1 + x2 + x3 + x4)
        du[1, :] = @. ((lambda0*x1/(1 + (lambda0/lambda1*w)^20)^(1/20) - k2*C*x1))
        du[2, :] = @. ((k2*C*x1 - k1*x2))
        du[3, :] = @. ((k1*(x2 - x3)))
        du[4, :] = @. ((k1*(x3 - x4)))
    end
    return nothing
end

function y0_batch(theta)
    ke_C = @view theta[1, :]
    V_C = @view theta[2, :]
    lambda0 = @view theta[3, :]
    lambda1 = @view theta[4, :]
    k1 = @view theta[5, :]
    k2 = @view theta[6, :]
    w0 = @view theta[7, :]
    zc = zero(eltype(theta)) .* @view theta[1, :]   # (N,) Null-Vektor
    i1 = @. (w0) + zc
    i2 = @. (0) + zc
    i3 = @. (0) + zc
    i4 = @. (0) + zc
    return permutedims(hcat(i1, i2, i3, i4))
end

function solve_batch(theta, latent, nn, dose, tspan, saveat;
                     solver = Tsit5(), abstol = 1e-4, reltol = 1e-4,
                     sensealg = nothing)
    p = ComponentArray(theta = theta)
    u0 = y0_batch(theta)
    prob = ODEProblem((du, u, pp, tt) -> f_batch!(du, u, pp, tt, dose), u0, tspan, p)
    ss = tspan[1] == first(saveat)
    return solve(prob, solver; verbose = ODE_SILENT, saveat = saveat, save_start = ss,
                 abstol = abstol, reltol = reltol, save_everystep = false,
                 sensealg = sensealg)
end

function observe_batch(u, theta, t, dose)
    @inbounds begin
        ke_C = @view theta[1, :]
        V_C = @view theta[2, :]
        lambda0 = @view theta[3, :]
        lambda1 = @view theta[4, :]
        k1 = @view theta[5, :]
        k2 = @view theta[6, :]
        w0 = @view theta[7, :]
        x1 = @view u[1, :]
        x2 = @view u[2, :]
        x3 = @view u[3, :]
        x4 = @view u[4, :]
        C = pkconc_bat_C(theta, dose, t)
        w = @. (x1 + x2 + x3 + x4)
        o1 = @. (w)
        return hcat(o1)
    end
end

# Predicted observations at (u, t) in OBS_NAMES order. p = (theta, latent, ..).
function observe(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        ke_C = theta[1]
        V_C = theta[2]
        lambda0 = theta[3]
        lambda1 = theta[4]
        k1 = theta[5]
        k2 = theta[6]
        w0 = theta[7]
        x1 = u[1]
        x2 = u[2]
        x3 = u[3]
        x4 = u[4]
        C = pkconc_C(t, theta, dose)
        w = x1 + x2 + x3 + x4
        return (w,)
    end
end

const OBSF_NP = 7
function obsf(u, p, t, dose)
    theta = view(p, 1:7)
    @inbounds begin
        ke_C = theta[1]
        V_C = theta[2]
        lambda0 = theta[3]
        lambda1 = theta[4]
        k1 = theta[5]
        k2 = theta[6]
        w0 = theta[7]
        x1 = u[1]
        x2 = u[2]
        x3 = u[3]
        x4 = u[4]
        C = pkconc_C(t, theta, dose)
        w = x1 + x2 + x3 + x4
        return SVector(w)
    end
end

const ALLVAR_NAMES = ("x1", "x2", "x3", "x4", "C", "w")
# Every model quantity at (u, t) in ALLVAR_NAMES order — for the results plots.
function allvars(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        ke_C = theta[1]
        V_C = theta[2]
        lambda0 = theta[3]
        lambda1 = theta[4]
        k1 = theta[5]
        k2 = theta[6]
        w0 = theta[7]
        x1 = u[1]
        x2 = u[2]
        x3 = u[3]
        x4 = u[4]
        C = pkconc_C(t, theta, dose)
        w = x1 + x2 + x3 + x4
        return (x1, x2, x3, x4, C, w)
    end
end

# Predict observations at `times` for one individual.
function predict(theta, latent, nn, dose, times)
    p = (theta = theta, latent = latent, nn = nn, dose = dose)
    tspan = (first(times), last(times))
    sol = solve_one(theta, latent, nn, dose, tspan, times)
    return [observe(sol.u[j], p, times[j]) for j in eachindex(times)]
end

end # module StructuralDecoder
